import{_ as t,o as a,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Muhurtam Activity Coverage Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"reference/45-muhurta-activity-coverage-roadmap.md","filePath":"reference/45-muhurta-activity-coverage-roadmap.md","lastUpdated":1788546361000}'),n={name:"reference/45-muhurta-activity-coverage-roadmap.md"};function o(d,e,s,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="muhurtam-activity-coverage-roadmap" tabindex="-1">Muhurtam Activity Coverage Roadmap <a class="header-anchor" href="#muhurtam-activity-coverage-roadmap" aria-label="Permalink to &quot;Muhurtam Activity Coverage Roadmap&quot;">​</a></h1><p>This is a source-coverage inventory, not an active implementation queue. Any candidate selected for work must first have a repository Issue and be placed in the <a href="https://github.com/users/socraticsurge/projects/2" target="_blank" rel="noreferrer">Telugu Calendar Utilities GitHub Project</a>.</p><p>The current selector has 36 activity keys, all with an explicit provenance state. That closes attribution ambiguity; it does not mean the activity catalogue is complete. The machine-readable gap inventory is <a href="muhurta-activity-backlog.json"><code>muhurta-activity-backlog.json</code></a>.</p><h2 id="immediate-finding-about-house-warming" tabindex="-1">Immediate finding about house warming <a class="header-anchor" href="#immediate-finding-about-house-warming" aria-label="Permalink to &quot;Immediate finding about house warming&quot;">​</a></h2><p>House warming is present as <code>gruhapravesha</code>, correctly narrowed to the first entry into a newly built home. Its former soft Tithi-family scoring has been replaced with Raman&#39;s exact weekday, Paksha-qualified Tithi, Nakshatra, Uttarayana and Lagna gates. Chart, ritual and pregnancy conditions remain visible manual prerequisites, while the current Drik Panchang Saturday/month methodology divergence is disclosed. See the <a href="./33-gruhapravesha-evidence-audit">Gruhapravesha source profile</a>. A completed-house purchase, rental move, post-renovation re-entry and first occupation of a newly built home remain separate acts.</p><h2 id="highest-impact-additions" tabindex="-1">Highest-impact additions <a class="header-anchor" href="#highest-impact-additions" aria-label="Permalink to &quot;Highest-impact additions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>Activity</th><th>Why it comes next</th></tr></thead><tbody><tr><td>1</td><td>Seemantha</td><td><strong>Implemented:</strong> source-verified profile with pregnancy and medical boundaries</td></tr><tr><td>2</td><td>Completed-house purchase</td><td><strong>Implemented:</strong> dedicated new/old completed-house profile</td></tr><tr><td>3</td><td>Home repair / renovation start</td><td><strong>Implemented:</strong> scoped repair-commencement profile</td></tr><tr><td>4</td><td>Buying inventory for trade</td><td><strong>Implemented:</strong> buyer-side inventory profile distinct from launch</td></tr><tr><td>5</td><td>Borrowing and lending</td><td><strong>Implemented:</strong> separate debtor- and creditor-side profiles</td></tr><tr><td>6</td><td>Gruhapravesha correction</td><td><strong>Implemented:</strong> conflicting soft profile replaced by exact Raman-lineage gates</td></tr><tr><td>7</td><td>Wedding correction</td><td><strong>Implemented:</strong> contradictory family scoring replaced by the complete Raman election crosswalk</td></tr><tr><td>8</td><td>Lawsuit-filing correction</td><td><strong>Implemented:</strong> generic Court proxies replaced by the exact Raman filing election</td></tr><tr><td>9</td><td>Litigation duplicate correction</td><td><strong>Implemented:</strong> legacy key now resolves to Court; unsupported Bhadra/legal scoring removed</td></tr><tr><td>10</td><td>Ceremony correction</td><td><strong>Implemented:</strong> generic Puja proxies replaced by the exact Shantika/Paushtika election</td></tr><tr><td>11</td><td>New Beginning correction</td><td><strong>Implemented:</strong> generic proxies replaced by the exact Dharma-kriya commencement election</td></tr><tr><td>12</td><td>Business correction</td><td><strong>Implemented:</strong> generic launch proxies replaced by the exact capital-deployment election</td></tr><tr><td>13</td><td>Job/Contract correction</td><td><strong>Implemented:</strong> conflated option narrowed to the exact employee service-entry election</td></tr></tbody></table><p>Seemantha, completed-house purchase, home-repair commencement and trade- inventory purchase, borrowing and lending are now implemented as separate, source-verified profiles with explicit medical, legal, safety and scope boundaries. Borrowing discloses its Chintamani divergence; lending discloses the current Drik Panchang Wednesday divergence. Gruhapravesha is now corrected and verified, with its published-practice divergence visible. The highest-priority unresolved item is deity installation, which remains specialist-only pending a bounded product design.</p><p>The Wedding profile is likewise corrected: exact lunar-month exceptions, Paksha-aware Tithis, weekday grades, Nakshatras, Nitya Yogas, Vishti and named Lagnas replace the former Purna/Jaya and fixed-class proxies. Pada and complete election judgment remain mandatory practitioner checks; the Drik browser now post-screens the three exact vacant-7th/Kuja/Shukra prohibitions without claiming the remaining conditions. The current Drik Panchang methodology divergence is visible.</p><p>The Court profile is now narrowly scoped to filing or initiating a lawsuit. Raman&#39;s weekday and Nakshatra rules, his recurring unfavorable-Tithi list and conservative Mesha-Lagna gate replace the former Tuesday and Tithi-family proxies. The remaining election-chart conditions are mandatory practitioner checks, and legal deadlines and professional counsel always take precedence.</p><h2 id="important-holds-and-splits" tabindex="-1">Important holds and splits <a class="header-anchor" href="#important-holds-and-splits" aria-label="Permalink to &quot;Important holds and splits&quot;">​</a></h2><ul><li>Pumsavana is on policy hold because the inspected source presents fetal sex selection and efficacy claims that the product must not endorse.</li><li>Garbhadhana requires consent, fertility and medical-safety language before implementation.</li><li>Agriculture must be split into ploughing, sowing, planting, pruning, harvesting and storage. A generic profile would be textually indefensible.</li><li>Deity installation is specialist-only: Raman explicitly says the summary is not a substitute for the full ritual and chart authorities.</li><li>Medicine preparation can never supersede pharmacy standards, qualified practice or clinical evidence.</li></ul><h2 id="one-feature-at-a-time-gate" tabindex="-1">One-feature-at-a-time gate <a class="header-anchor" href="#one-feature-at-a-time-gate" aria-label="Permalink to &quot;One-feature-at-a-time gate&quot;">​</a></h2><p>For each addition:</p><ol><li>inspect the complete passage and at least one independent authority;</li><li>record exact edition/page/verse locators and disagreements;</li><li>write the rule crosswalk and tests before implementation;</li><li>add a new activity module/profile without changing the frozen engines;</li><li>expose identical provenance and decisive rules through MCP and browser;</li><li>capture browser screenshots and obtain owner sign-off before pushing;</li><li>run the full verifier and stop after the feature is concluded.</li></ol><p>Candidate locators in the backlog prove discoverability only. They do not grant <code>verified</code> status to any future activity.</p>',16)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
